library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all; use work.bb_util_pkg.all;
entity bbq_dual_port_ram_core is generic(DATA_WIDTH:positive:=32;DEPTH:positive:=256);port(clk:in std_logic;a_en,a_we:in std_logic;a_addr:in std_logic_vector(clog2(DEPTH)-1 downto 0);a_wdata:in std_logic_vector(DATA_WIDTH-1 downto 0);a_rdata:out std_logic_vector(DATA_WIDTH-1 downto 0);b_en,b_we:in std_logic;b_addr:in std_logic_vector(clog2(DEPTH)-1 downto 0);b_wdata:in std_logic_vector(DATA_WIDTH-1 downto 0);b_rdata:out std_logic_vector(DATA_WIDTH-1 downto 0));end;
architecture rtl of bbq_dual_port_ram_core is type mem_t is array(0 to DEPTH-1)of std_logic_vector(DATA_WIDTH-1 downto 0);signal mem:mem_t:=(others=>(others=>'0'));signal ar,br:std_logic_vector(DATA_WIDTH-1 downto 0):=(others=>'0');begin a_rdata<=ar;b_rdata<=br;process(clk)begin if rising_edge(clk)then if a_en='1'then if a_we='1'then mem(to_integer(unsigned(a_addr)))<=a_wdata;end if;ar<=mem(to_integer(unsigned(a_addr)));end if;if b_en='1'then if b_we='1'then mem(to_integer(unsigned(b_addr)))<=b_wdata;end if;br<=mem(to_integer(unsigned(b_addr)));end if;end if;end process;end architecture;
